                        r"cat\s+(?:>\s*(?:/app/)?reconcile\.py\s+<<\s*['\"]?([A-Za-z0-9_]+)['\"]?|<<\s*['\"]?([A-Za-z0-9_]+)['\"]?\s*>\s*(?:/app/)?reconcile\.py)\n(.*)",
                        ks,
                        re.DOTALL,
                    )
                    if m:
                        delim = m.group(1) or m.group(2)
                        rest = m.group(3)
                        lines = rest.splitlines()
                        body_lines = []
                        found_end = False
                        for ln in lines:
                            if ln.strip() == delim:
                                found_end = True
                                break
                            body_lines.append(ln)
                        if found_end:
                            write_events.append((sid, tc.get("tool_call_id"), "heredoc", "\n".join(body_lines) + "\n"))
                    elif "apply_patch" in ks:
                        if "apply_patch: command not found" in obs_text:
                            print(f"    -> skipped failed apply_patch")
                        else:
                            print(f"    -> WARNING: apply_patch succeeded? check manually!")
                    elif any(tok in first_line for tok in ("sed -i", "python3", "tee", "mv ", "cp ", "echo ")):
                        if "reconcile.py" in first_line and not first_line.startswith(("python3 /app/reconcile.py", "python3 reconcile.py", "chmod", "cat ", "sed -n")):
                            print(f"    -> NOTE: other mutating command on reconcile.py: {ks[:200]!r}")
        if write_events:
            sid, tcid, kind, content = write_events[-1]
            out_path = OUT_DIR / f"{trial_id}_reconcile.py"
            out_path.write_bytes(content.replace("\r\n", "\n").encode("utf-8"))
            print(f"  SAVED {out_path.name} from step {sid} ({tcid}, {len(content.splitlines())} lines)")
        else:
            print(f"  ERROR: no heredoc write found for {trial_id}!")

